using Avalonia.Media;
using Avalonia.Styling;

namespace Thirteen.Desktop.Themes;

/// <summary>A colour theme, chosen in Settings. Independent of light and dark, except for the always-dark themes.</summary>
public enum ThirteenTheme
{
    /// <summary>Almanac: Warm paper and iron-gall ink with a signal orange accent.</summary>
    Almanac,
    /// <summary>Graphite: Neutral greys with an electric blue accent.</summary>
    Graphite,
    /// <summary>Slate: Cool slate paper with a terracotta accent.</summary>
    Slate,
    /// <summary>Forest: Bone paper and deep green ink with an amber accent.</summary>
    Forest,
    /// <summary>Mono: Black and white only, with a quiet blue grey for the Gregorian side.</summary>
    Mono,
    /// <summary>Obsidian: Near black for OLED screens, warm ink and the signal orange. Always dark.</summary>
    Obsidian,
    /// <summary>Midnight: Deep navy with a teal accent and periwinkle for the Gregorian side. Always dark.</summary>
    Midnight,
    /// <summary>Phosphor: Green black like an old terminal, phosphor green and amber. Always dark.</summary>
    Phosphor,
}

/// <summary>How Settings groups the themes: the ones that follow light and dark first, then the always-dark ones.</summary>
public enum ThemeGroup
{
    /// <summary>Light and dark: Follows the system, or the Appearance setting.</summary>
    Adaptive,
    /// <summary>Dark: Always dark, whatever the system or the Appearance setting.</summary>
    Dark,
}

/// <summary>The colour roles of one theme in one mode (design/tokens.json "roles").</summary>
public sealed class ThemePalette
{
    /// <summary>Page background.</summary>
    public required Color Paper { get; init; }

    /// <summary>Cards, popovers and raised surfaces.</summary>
    public required Color PaperRaised { get; init; }

    /// <summary>Wells, grid cells and inset surfaces.</summary>
    public required Color PaperSunk { get; init; }

    /// <summary>Primary text (12:1 or more on every paper).</summary>
    public required Color Ink { get; init; }

    /// <summary>Secondary text (7:1 or more on every paper).</summary>
    public required Color InkSecondary { get; init; }

    /// <summary>Tertiary text and captions (4.5:1 or more on every paper).</summary>
    public required Color InkTertiary { get; init; }

    /// <summary>Hairlines and card strokes.</summary>
    public required Color Rule { get; init; }

    /// <summary>Faint dividers inside a surface.</summary>
    public required Color RuleSoft { get; init; }

    /// <summary>Emphasised rules: the almanac's heavy lines.</summary>
    public required Color RuleStrong { get; init; }

    /// <summary>The theme's signal colour for fills and marks: today, progress, selection. Not for body text.</summary>
    public required Color Accent { get; init; }

    /// <summary>Accent for text and icons on paper and on accent-wash (4.5:1 or more).</summary>
    public required Color AccentText { get; init; }

    /// <summary>Soft opaque accent fill behind accent text.</summary>
    public required Color AccentWash { get; init; }

    /// <summary>Translucent accent tint for hover and selected backgrounds.</summary>
    public required Color AccentSoft { get; init; }

    /// <summary>Text and glyphs on a solid accent fill.</summary>
    public required Color OnAccent { get; init; }

    /// <summary>Tint of system controls (Apple .tint, Android and Windows control accents). Light: 4.5:1 or more on paper. Dark: 4.5:1 or more on every paper, and white text on it 3:1 or more.</summary>
    public required Color ControlTint { get; init; }

    /// <summary>The Gregorian foil: everything 12-month, in a colour clearly apart from the accent.</summary>
    public required Color Foil { get; init; }

    /// <summary>Soft opaque foil fill behind foil text.</summary>
    public required Color FoilWash { get; init; }

    /// <summary>Translucent foil tint.</summary>
    public required Color FoilSoft { get; init; }

    /// <summary>Text and glyphs on a solid foil fill.</summary>
    public required Color OnFoil { get; init; }

    /// <summary>Keyboard focus ring (3:1 or more against paper).</summary>
    public required Color Focus { get; init; }

    /// <summary>Translucent overlay behind sheets and dialogs.</summary>
    public required Color Scrim { get; init; }

    /// <summary>Tint of the paper grain texture (web).</summary>
    public required Color Grain { get; init; }

    /// <summary>Colour of drop shadows (alpha comes from "shadows").</summary>
    public required Color Shadow { get; init; }
}

